+            }
+        }
+        $parts.Add("$state - $($clauses.ToArray() -join ', ')")
+    }
+    $tail = "$a of $n $noun available"
+    if ($c -gt 0) { $tail += ", $o out, $c not checked" }
+    $parts.Add($tail)
+    return "$Prefix$($parts.ToArray() -join '; ')$Suffix"
+}
